// Package resetgen generates Reset methods for structs marked with generate:reset.
package resetgen

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const (
	directive  = "generate:reset"
	outputName = "reset.gen.go"
)

type markedStruct struct {
	name   string
	typeOf *types.Named
}

// Generate scans packages below root and writes reset.gen.go for marked structs.
// Existing generated files are updated only when their contents change.
func Generate(root string) error {
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return fmt.Errorf("resolve project root: %w", err)
	}
	mode := packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
		packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedImports | packages.NeedDeps
	pkgs, err := packages.Load(&packages.Config{Dir: absRoot, Mode: mode}, "./...")
	if err != nil {
		return fmt.Errorf("load project packages: %w", err)
	}
	if packages.PrintErrors(pkgs) != 0 {
		return fmt.Errorf("load project packages: package errors reported")
	}

	for _, pkg := range pkgs {
		if err := generatePackage(pkg); err != nil {
			return err
		}
	}
	return nil
}

func generatePackage(pkg *packages.Package) error {
	var marked []markedStruct
	generatedMethods, err := readGeneratedMethods(pkg.Dir)
	if err != nil {
		return err
	}
	for _, file := range pkg.Syntax {
		filename := pkg.Fset.Position(file.Pos()).Filename
		if filepath.Base(filename) == outputName {
			continue
		}
		if strings.HasSuffix(filename, "_test.go") || ast.IsGenerated(file) {
			continue
		}

		for _, decl := range file.Decls {
			genDecl, ok := decl.(*ast.GenDecl)
			if !ok || genDecl.Tok != token.TYPE {
				continue
			}
			declMarked := hasDirective(genDecl.Doc)
			for _, spec := range genDecl.Specs {
				typeSpec := spec.(*ast.TypeSpec)
				if !declMarked && !hasDirective(typeSpec.Doc) {
					continue
				}
				if _, ok := typeSpec.Type.(*ast.StructType); !ok {
					return fmt.Errorf("%s: %s: %s requires a struct type", filename, pkg.Name, typeSpec.Name.Name)
				}
				object, ok := pkg.TypesInfo.Defs[typeSpec.Name].(*types.TypeName)
				if !ok {
					return fmt.Errorf("%s: cannot resolve type %s", filename, typeSpec.Name.Name)
				}
				named, ok := types.Unalias(object.Type()).(*types.Named)
				if !ok {
					return fmt.Errorf("%s: %s is an alias and cannot have a Reset method", filename, typeSpec.Name.Name)
				}
				if named.TypeParams() != nil && named.TypeParams().Len() != 0 {
					return fmt.Errorf("%s: generic struct %s is not supported", filename, typeSpec.Name.Name)
				}
				if _, ok := named.Underlying().(*types.Struct); !ok {
					return fmt.Errorf("%s: %s does not have a struct underlying type", filename, typeSpec.Name.Name)
				}
				if hasResetMethod(named) && !generatedMethods[typeSpec.Name.Name] {
					return fmt.Errorf("%s: %s already has a Reset method", filename, typeSpec.Name.Name)
				}
				marked = append(marked, markedStruct{name: typeSpec.Name.Name, typeOf: named})
			}
		}
	}

	path := filepath.Join(pkg.Dir, outputName)
	if len(marked) == 0 {
		if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
			return fmt.Errorf("remove stale %s: %w", path, err)
		}
		return nil
	}

	sort.Slice(marked, func(i, j int) bool { return marked[i].name < marked[j].name })
	generated := make(map[*types.TypeName]bool, len(marked))
	for _, item := range marked {
		generated[item.typeOf.Obj()] = true
	}

	var source strings.Builder
	source.WriteString("// Code generated by cmd/reset; DO NOT EDIT.\n\npackage ")
	source.WriteString(pkg.Name)
	source.WriteString("\n\n")
	for _, item := range marked {
		method, err := generateMethod(item, pkg.Types.Path(), generated)
		if err != nil {
			return fmt.Errorf("generate %s.Reset in %s: %w", item.name, pkg.PkgPath, err)
		}
		source.WriteString(method)
		source.WriteByte('\n')
	}

	formatted, err := format.Source([]byte(source.String()))
	if err != nil {
		return fmt.Errorf("format %s: %w", path, err)
	}
	previous, err := os.ReadFile(path)
	if err == nil && bytes.Equal(previous, formatted) {
		return nil
	}
	if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("read %s: %w", path, err)
	}
	if err := os.WriteFile(path, formatted, 0644); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

func readGeneratedMethods(dir string) (map[string]bool, error) {
	generated := make(map[string]bool)
	path := filepath.Join(dir, outputName)
	file, err := parser.ParseFile(token.NewFileSet(), path, nil, 0)
	if os.IsNotExist(err) {
		return generated, nil
	}
	if err != nil {
		return nil, fmt.Errorf("parse generated methods in %s: %w", path, err)
	}
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if ok && fn.Name.Name == "Reset" && fn.Recv != nil && len(fn.Recv.List) == 1 {
			if name := receiverTypeName(fn.Recv.List[0].Type); name != "" {
				generated[name] = true
			}
		}
	}
	return generated, nil
}

func generateMethod(item markedStruct, packagePath string, generated map[*types.TypeName]bool) (string, error) {
	var source strings.Builder
	source.WriteString("// Reset clears the receiver while retaining allocated slices and maps.\n")
	fmt.Fprintf(&source, "func (s *%s) Reset() {\n\tif s == nil {\n\t\treturn\n\t}\n", item.name)
	structure := item.typeOf.Underlying().(*types.Struct)
	for i := 0; i < structure.NumFields(); i++ {
		field := structure.Field(i)
		if field.Name() == "_" {
			return "", fmt.Errorf("blank embedded fields cannot be reset")
		}
		statements, err := resetValue("s."+field.Name(), field.Type(), packagePath, generated, make(map[*types.TypeName]bool), 0)
		if err != nil {
			return "", fmt.Errorf("field %s: %w", field.Name(), err)
		}
		for _, statement := range statements {
			source.WriteString("\t\t")
			source.WriteString(statement)
			source.WriteByte('\n')
		}
	}
	source.WriteString("\t}\n")
	return source.String(), nil
}

func resetValue(expr string, typ types.Type, packagePath string, generated map[*types.TypeName]bool, stack map[*types.TypeName]bool, depth int) ([]string, error) {
	if depth > 32 {
		return nil, fmt.Errorf("nested field type is too deep")
	}
	typ = types.Unalias(typ)
	if _, ok := typ.(*types.TypeParam); ok {
		return nil, fmt.Errorf("type parameters are not supported")
	}
	if pointer, ok := typ.(*types.Pointer); ok {
		inner, err := resetValue("(*"+expr+")", pointer.Elem(), packagePath, generated, stack, depth+1)
		if err != nil {
			return nil, err
		}
		return wrapBlock("if "+expr+" != nil", inner), nil
	}

	if named, ok := typ.(*types.Named); ok {
		if _, isStruct := named.Underlying().(*types.Struct); isStruct {
			if hasResetMethod(named) || generated[named.Obj()] {
				return []string{expr + ".Reset()"}, nil
			}
			if named.Obj().Pkg() != nil && named.Obj().Pkg().Path() != packagePath {
				return nil, fmt.Errorf("external struct %s has no accessible Reset method", named.Obj().Name())
			}
			if stack[named.Obj()] {
				return nil, fmt.Errorf("recursive struct %s needs its own Reset method", named.Obj().Name())
			}
			stack[named.Obj()] = true
			fields, err := resetStruct(expr, named.Underlying().(*types.Struct), packagePath, generated, stack, depth+1)
			delete(stack, named.Obj())
			return fields, err
		}
		typ = named.Underlying()
	}

	switch value := typ.Underlying().(type) {
	case *types.Basic:
		zero, err := zeroValue(value)
		if err != nil {
			return nil, err
		}
		return []string{expr + " = " + zero}, nil
	case *types.Slice:
		return []string{expr + " = " + expr + "[:0]"}, nil
	case *types.Map:
		return []string{"clear(" + expr + ")"}, nil
	case *types.Interface:
		return []string{expr + " = nil"}, nil
	case *types.Chan, *types.Signature:
		return []string{expr + " = nil"}, nil
	case *types.Array:
		index := fmt.Sprintf("resetIndex%d", depth)
		body, err := resetValue(expr+"["+index+"]", value.Elem(), packagePath, generated, stack, depth+1)
		if err != nil {
			return nil, err
		}
		return wrapFor(index, expr, body), nil
	case *types.Struct:
		return resetStruct(expr, value, packagePath, generated, stack, depth+1)
	case *types.TypeParam:
		return nil, fmt.Errorf("type parameters are not supported")
	default:
		return nil, fmt.Errorf("unsupported field type %s", types.TypeString(typ, nil))
	}
}

func resetStruct(expr string, structure *types.Struct, packagePath string, generated map[*types.TypeName]bool, stack map[*types.TypeName]bool, depth int) ([]string, error) {
	var statements []string
	for i := 0; i < structure.NumFields(); i++ {
		field := structure.Field(i)
		if field.Name() == "_" {
			return nil, fmt.Errorf("blank embedded fields cannot be reset")
		}
		fieldStatements, err := resetValue(expr+"."+field.Name(), field.Type(), packagePath, generated, stack, depth+1)
		if err != nil {
			return nil, fmt.Errorf("nested field %s: %w", field.Name(), err)
		}
		statements = append(statements, fieldStatements...)
	}
	return statements, nil
}

func zeroValue(basic *types.Basic) (string, error) {
	switch {
	case basic.Info()&types.IsBoolean != 0:
		return "false", nil
	case basic.Info()&types.IsString != 0:
		return `""`, nil
	case basic.Info()&(types.IsInteger|types.IsFloat|types.IsComplex) != 0:
		return "0", nil
	case basic.Kind() == types.UnsafePointer:
		return "nil", nil
	default:
		return "", fmt.Errorf("unsupported primitive %s", basic.Name())
	}
}

func hasResetMethod(named *types.Named) bool {
	method := types.NewMethodSet(types.NewPointer(named)).Lookup(named.Obj().Pkg(), "Reset")
	return method != nil
}

func hasDirective(group *ast.CommentGroup) bool {
	if group == nil {
		return false
	}
	for _, comment := range group.List {
		if strings.TrimSpace(strings.TrimPrefix(comment.Text, "//")) == directive {
			return true
		}
	}
	return false
}

func receiverTypeName(expr ast.Expr) string {
	if pointer, ok := expr.(*ast.StarExpr); ok {
		expr = pointer.X
	}
	if name, ok := expr.(*ast.Ident); ok {
		return name.Name
	}
	return ""
}

func wrapBlock(header string, body []string) []string {
	result := []string{header + " {"}
	for _, line := range body {
		result = append(result, "\t"+line)
	}
	return append(result, "}")
}

func wrapFor(index, expr string, body []string) []string {
	result := []string{"for " + index + " := range " + expr + " {"}
	for _, line := range body {
		result = append(result, "\t"+line)
	}
	return append(result, "}")
}
